//! Real private TaskCursor DTO, not a surrogate Registry/continuation/host.
use super::*;
fn nominal()->Value{Value::Enum(rvn_parser::enum_asset::EnumValue{asset:rvn_parser::enum_asset::EnumAssetId::parse("329f41eae6ba4b4bb71dfaf60fb50001").unwrap(),member:rvn_parser::enum_asset::EnumMemberId::parse("229f41eae6ba4b4bb71dfaf60fb50001").unwrap()})}
#[test] fn enum_cursor1025_actual_each_next_erased_future_items_are_in_inventory(){let value=nominal();let cursor=TaskCursor{kind:"each_next".into(),ctx:None,data:serde_json::to_value(vec![value.clone()]).unwrap()};let Value::Enum(expected)=value else{unreachable!()};assert_eq!(crate::save_enum_values1025::collect(&cursor).unwrap(),vec![expected]);}
#[test] fn enum_cursor1025_actual_choice_erased_rows_are_in_inventory(){for kind in ["consumer_choice","consumer_choice_selected","consumer_choice_label"]{let value=nominal();let cursor=TaskCursor{kind:kind.into(),ctx:None,data:serde_json::to_value((0usize,vec![value.clone()])).unwrap()};let Value::Enum(expected)=value else{unreachable!()};assert_eq!(crate::save_enum_values1025::collect(&cursor).unwrap(),vec![expected]);}}
#[test] fn enum_cursor1025_identical_user_json_keys_never_become_typed_cursor_authority(){let cursor=TaskCursor{kind:"each_next".into(),ctx:None,data:serde_json::to_value(vec![nominal()]).unwrap()};let user_data=serde_json::to_value(cursor).unwrap();assert!(crate::save_enum_values1025::collect(&user_data).unwrap().is_empty());}
#[test] fn enum_cursor1025_unknown_kind_cannot_hide_a_new_runtime_value_payload(){let cursor=TaskCursor{kind:"future_unowned_value_cursor".into(),ctx:None,data:serde_json::to_value(vec![nominal()]).unwrap()};assert!(crate::save_enum_values1025::collect(&cursor).is_err());}
#[test] fn enum_cursor1025_malformed_and_oversized_actual_each_payloads_refuse(){for data in [serde_json::json!("not items"),serde_json::to_value(vec![Value::Bool(false);crate::value_limits::MAX_COLLECTION_ITEMS+1]).unwrap()]{let cursor=TaskCursor{kind:"each_next".into(),ctx:None,data};assert!(crate::save_enum_values1025::collect(&cursor).is_err());}}

#[test] fn enum_cursor1025_each_cardinality_refuses_before_invalid_rows_typed_decode(){let cursor=TaskCursor{kind:"each_next".into(),ctx:None,data:serde_json::to_value(vec![serde_json::json!({"not_a_runtime_value":0});crate::value_limits::MAX_COLLECTION_ITEMS+1]).unwrap()};let error=crate::save_enum_values1025::collect(&cursor).unwrap_err();assert!(error.to_string().contains("existing collection budget"),"{error}");}
#[test] fn enum_cursor1025_choice_cardinality_refuses_before_invalid_rows_typed_decode(){let cursor=TaskCursor{kind:"consumer_choice".into(),ctx:None,data:serde_json::json!([0,vec![serde_json::json!({"not_a_runtime_value":0});crate::value_limits::MAX_COLLECTION_ITEMS+1]])};let error=crate::save_enum_values1025::collect(&cursor).unwrap_err();assert!(error.to_string().contains("existing collection budget"),"{error}");}
#[test] fn enum_cursor1025_existing_byte_budget_precedes_shape_and_typed_allocation(){let cursor=TaskCursor{kind:"each_next".into(),ctx:None,data:serde_json::Value::String("x".repeat(crate::save::consumer_checkpoint::Save15::MAX_BYTES+1))};let error=crate::save_enum_values1025::collect(&cursor).unwrap_err();assert!(error.to_string().contains("byte budget"),"{error}");}
